use std::io

fn main() {
    let mut sieve = Vec::new()
    let mut i = 0
    while i <= 200000 {
        sieve.push(true)
        i += 1
    }
    let mut cnt: Vec<int> = Vec::new()
    let mut last: Vec<int> = Vec::new()
    let mut c = 0
    let mut l = -1
    i = 0
    while i <= 200000 {
        if i >= 2 && sieve[i] {
            c += 1
            l = i
            let mut j = i * i
            while j <= 200000 {
                sieve[j] = false
                j += i
            }
        }
        cnt.push(c)
        last.push(l)
        i += 1
    }
    let t: int = (io::read_line() ?? "").trim().parse() ?? 0
    let mut k = 0
    while k < t {
        let n: int = (io::read_line() ?? "").trim().parse() ?? 0
        if n < 2 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
        k += 1
    }
}

